#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <microhttpd.h>
#include <curl/curl.h>
#include <ctype.h>

#define MAX_TEMPLATE 4096
#define MAX_TOKEN 256
#define AUTH_SERVICE "http://auth-service:8081/verify"

typedef struct {
    char *data;
    size_t len;
} response_buf_t;

static size_t write_cb(void *ptr, size_t size, size_t nmemb, void *userdata) {
    response_buf_t *buf = (response_buf_t *)userdata;
    size_t total = size * nmemb;
    if (buf->len + total > 65536) return 0; /* limit response size */
    buf->data = realloc(buf->data, buf->len + total + 1);
    if (!buf->data) return 0;
    memcpy(buf->data + buf->len, ptr, total);
    buf->len += total;
    buf->data[buf->len] = '\0';
    return total;
}

static int verify_token_with_auth_service(const char *token, char *username_out, size_t out_sz) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    /* Validate token format before sending - alphanumeric and hyphens only */
    for (const char *t = token; *t; t++) {
        if (!isalnum((unsigned char)*t) && *t != '-' && *t != '_' && *t != '.') {
            curl_easy_cleanup(curl);
            return -1;
        }
    }

    response_buf_t resp = {NULL, 0};
    char url[512];
    snprintf(url, sizeof(url), "%s?token=%s", AUTH_SERVICE, token);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &resp);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_PROTOCOLS, CURLPROTO_HTTP | CURLPROTO_HTTPS);

    CURLcode res = curl_easy_perform(curl);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK || !resp.data) {
        free(resp.data);
        return -1;
    }

    /* Auth service returns: {"valid":true,"username":"...","role":"..."} */
    char *ustart = strstr(resp.data, "\"username\":\"");
    if (!ustart) { free(resp.data); return -1; }
    ustart += 12;
    char *uend = strchr(ustart, '"');
    if (!uend) { free(resp.data); return -1; }

    size_t ulen = uend - ustart;
    if (ulen >= out_sz) ulen = out_sz - 1;
    memcpy(username_out, ustart, ulen);
    username_out[ulen] = '\0';

    free(resp.data);
    return 0;
}

/* Template engine: replaces {{variable}} with values from context */
typedef struct {
    const char *key;
    const char *value;
} tmpl_var_t;

static int sanitize_for_html(const char *input, char *output, size_t outsz) {
    size_t j = 0;
    for (size_t i = 0; input[i] && j < outsz - 6; i++) {
        switch (input[i]) {
            case '<': memcpy(output+j, "&lt;", 4); j+=4; break;
            case '>': memcpy(output+j, "&gt;", 4); j+=4; break;
            case '&': memcpy(output+j, "&amp;", 5); j+=5; break;
            case '"': memcpy(output+j, "&quot;", 6); j+=6; break;
            case '\'': memcpy(output+j, "&#39;", 5); j+=5; break;
            default: output[j++] = input[i]; break;
        }
    }
    output[j] = '\0';
    return 0;
}

static int render_template(const char *tmpl, tmpl_var_t *vars, int nvars, char *out, size_t outsz) {
    size_t pos = 0;
    const char *p = tmpl;

    while (*p && pos < outsz - 1) {
        if (p[0] == '{' && p[1] == '{') {
            p += 2;
            while (*p == ' ') p++;

            char varname[64] = {0};
            int vi = 0;
            while (*p && !(*p == '}' && *(p+1) == '}') && *p != ' ' && vi < 63) {
                varname[vi++] = *p++;
            }
            while (*p == ' ') p++;
            if (*p == '}' && *(p+1) == '}') p += 2;

            for (int i = 0; i < nvars; i++) {
                if (strcmp(vars[i].key, varname) == 0) {
                    size_t vlen = strlen(vars[i].value);
                    if (pos + vlen < outsz) {
                        memcpy(out + pos, vars[i].value, vlen);
                        pos += vlen;
                    }
                    break;
                }
            }
        } else {
            out[pos++] = *p++;
        }
    }
    out[pos] = '\0';
    return 0;
}

/* The greeting template - hardcoded, immutable */
static const char * const G_GREETING_TEMPLATE =
    "<html><body><h1>Welcome, {{username}}!</h1>"
    "<p>Your dashboard is ready.</p></body></html>";

static enum MHD_Result request_handler(
    void *cls, struct MHD_Connection *conn,
    const char *url, const char *method,
    const char *version, const char *upload_data,
    size_t *upload_data_size, void **con_cls)
{
    (void)cls; (void)version; (void)upload_data; (void)upload_data_size; (void)con_cls;

    const char *token = MHD_lookup_connection_value(conn, MHD_HEADER_KIND, "Authorization");
    if (!token) {
        const char *err = "Unauthorized";
        struct MHD_Response *resp = MHD_create_response_from_buffer(strlen(err), (void*)err, MHD_RESPMEM_PERSISTENT);
        enum MHD_Result ret = MHD_queue_response(conn, 401, resp);
        MHD_destroy_response(resp);
        return ret;
    }

    if (strcmp(url, "/dashboard") == 0 && strcmp(method, "GET") == 0) {
        char username[128];
        if (verify_token_with_auth_service(token, username, sizeof(username)) != 0) {
            const char *err = "Auth failed";
            struct MHD_Response *resp = MHD_create_response_from_buffer(strlen(err), (void*)err, MHD_RESPMEM_PERSISTENT);
            enum MHD_Result ret = MHD_queue_response(conn, 403, resp);
            MHD_destroy_response(resp);
            return ret;
        }

        /* Sanitize username for safe HTML embedding */
        char safe_username[512];
        sanitize_for_html(username, safe_username, sizeof(safe_username));

        tmpl_var_t vars[] = {
            {"username", safe_username}
        };

        char rendered[MAX_TEMPLATE];
        render_template(G_GREETING_TEMPLATE, vars, 1, rendered, sizeof(rendered));

        struct MHD_Response *resp = MHD_create_response_from_buffer(strlen(rendered), rendered, MHD_RESPMEM_MUST_COPY);
        MHD_add_response_header(resp, "Content-Type", "text/html");
        MHD_add_response_header(resp, "X-Content-Type-Options", "nosniff");
        MHD_add_response_header(resp, "Content-Security-Policy", "default-src 'none'");
        enum MHD_Result ret = MHD_queue_response(conn, 200, resp);
        MHD_destroy_response(resp);
        return ret;
    }

    const char *nf = "Not Found";
    struct MHD_Response *resp = MHD_create_response_from_buffer(strlen(nf), (void*)nf, MHD_RESPMEM_PERSISTENT);
    enum MHD_Result ret = MHD_queue_response(conn, 404, resp);
    MHD_destroy_response(resp);
    return ret;
}

int main(int argc, char **argv) {
    (void)argc; (void)argv;

    struct MHD_Daemon *d = MHD_start_daemon(
        MHD_USE_THREAD_PER_CONNECTION, 8080, NULL, NULL,
        &request_handler, NULL, MHD_OPTION_END);

    if (!d) { fprintf(stderr, "Failed to start server\n"); return 1; }
    printf("Template service running on :8080\n");
    getchar();
    MHD_stop_daemon(d);
    return 0;
}
